function przejdzDoZakladki(nazwa) {
  const stan = { zakladka: nazwa, czas: Date.now() };
  const url = `?zakladka=${nazwa}`;

  history.pushState(stan, "", url);
  console.log("Nowy URL:", location.href); // zmieniony, bez przeladowania
}

przejdzDoZakladki("produkty");
// -> "Nowy URL: .../strona?zakladka=produkty"

window.addEventListener("popstate", (e) => {
  const zakladka = e.state?.zakladka ?? "domyslna";
  console.log("Powrot do zakladki:", zakladka);
  // tutaj: ponowne wyrenderowanie odpowiedniej tresci na podstawie e.state
});

function renderZakladka(zakladka) {
  const tresci = {
    home: "Zawartosc: Home",
    produkty: "Zawartosc: Produkty",
    onas: "Zawartosc: O nas",
  };
  document.getElementById("tab-content").textContent =
    tresci[zakladka] ?? "Nieznana zakladka";
}

function przejdzDoZakladki(zakladka) {
  history.pushState({ zakladka }, "", `?zakladka=${zakladka}`);
  renderZakladka(zakladka); // renderuj OD RAZU, bo pushState tego nie robi
}

window.addEventListener("popstate", (e) => {
  renderZakladka(e.state?.zakladka ?? "home"); // ta sama funkcja renderujaca
});

function zleNawiguj(zakladka) {
  history.pushState({ zakladka }, "", `?zakladka=${zakladka}`);
  // BRAK wywolania funkcji renderujacej - DOM pozostaje bez zmian!
}

function dobrzeNawiguj(zakladka) {
  history.pushState({ zakladka }, "", `?zakladka=${zakladka}`);
  renderZakladka(zakladka); // DOBRZE - reczna aktualizacja DOM
}

exercises.solution:
function przejdzDoKroku(numer) {
  history.pushState({ krok: numer }, "", `?krok=${numer}`);
}

przejdzDoKroku(2);
console.log(location.href); // zawiera "?krok=2"

function renderKrok(numer) {
  console.log(`Renderuje krok: ${numer}`);
}

function przejdzDoKrokuZRenderowaniem(numer) {
  history.pushState({ krok: numer }, "", `?krok=${numer}`);
  renderKrok(numer);
}

przejdzDoKrokuZRenderowaniem(3); // "Renderuje krok: 3"

history.replaceState({ poprawiono: true }, "", "?wersja=2");
// W odroznieniu od pushState, replaceState NIE dodaje nowego wpisu do
// historii nawigacji - zastepuje AKTUALNY wpis. Przycisk 'Wstecz'
// pominie ten krok, jakby go wcale nie bylo - dobre do 'cichych'
// korekt URL, ktore nie powinny tworzyc osobnego kroku nawigacji.

// Uzytkownik moze dotrzec do danego widoku na DWA sposoby: klikajac
// link/zakladke wewnatrz strony (co wywoluje pushState) LUB uzywajac
// przyciskow Wstecz/Naprzod przegladarki (co wywoluje popstate). Jesli
// kazda z tych sciezek renderowalaby zawartosc INNA funkcja (lub z inna
// logika), latwo o niespojnosc - np. widok po kliknieciu 'Wstecz' moze
// wygladac inaczej niz ten sam widok osiagniety przez klikniecie linku.
// Wywolywanie JEDNEJ, wspolnej funkcji renderujacej w obu miejscach
// gwarantuje, ze zawartosc jest zawsze spojna z aktualnym stanem URL,
// niezaleznie od sposobu nawigacji.
